CREATE function [dbo].[funcGetVoucherDesc](@VN nvarchar(50),@VoucherId int,@CAId int )returns nvarchar(MAX) as Begin Declare @Desc nvarchar(MAX); set @Desc = ''; if @VN like 'BPV%' Begin select @Desc = id.[Desc] from BankPaymentMaster i inner join BankPaymentDetail id on i.BPId = id.BPId where i.BPId = @VoucherId  and id.CAId = @CAId if @Desc = '' Begin set @Desc = ''; SELECT @Desc = COALESCE(@Desc + ', ', '') + [Desc] FROM BankPaymentDetail  where BPId = @VoucherId  End End else if @VN like 'CPV%' Begin select @Desc = id.[Desc] from CashPaymentMaster i  inner join CashPaymentDetail id on i.CPId = id.CPId where i.CPId = @VoucherId  and id.CAId = @CAId if @Desc = '' Begin set @Desc = ''; SELECT @Desc = COALESCE(@Desc + ', ', '') + [Desc] FROM CashPaymentDetail where CPId = @VoucherId  End End else if @VN like 'CRV%' Begin select @Desc = id.[Desc] from CashReceiptMaster i  inner join CashReceiptDetail id on i.CRId = id.CRId where i.CRId = @VoucherId and id.CAId = @CAId End else if @VN like 'BRV%' Begin select @Desc = id.[Desc] from BankReceiptMaster i inner join BankReceiptDetail id on i.BRId = id.BRId where i.BRId = @VoucherId and id.CAId = @CAId End else if @VN like 'INV%' Begin select @Desc = id.[Desc] from InvoiceMaster_CompanyNew i  inner join GRNMaster id on i.vid = id.vid and i.refrenceno=id.refrenceno where i.InvoiceId = @VoucherId  End else if @VN like 'JV%' Begin select @Desc = id.[Desc] from JVMaster i  inner join JVDetail id on i.JVId = id.JVId where i.JVId = @VoucherId and id.CAId = @CAId End else if @VN like 'PV%' Begin select @Desc = id.[Desc] from InvoiceMaster i  inner join InvoiceDetail id on i.InvoiceId = id.InvoiceId where i.InvoiceId = @VoucherId and id.CAId = @CAId End else if @VN like 'ISS%' Begin select @Desc = i.[Desc] from IssuanceMaster_Store i  inner join IssuanceDetail_Store id on i.issid = id.issid where i.issid = @VoucherId End else if @VN like 'SRV%' Begin select @Desc = id.[Desc] from SaleReturnMaster i  inner join SaleReturnDetail id on i.SRId = id.SRId where i.SRId = @VoucherId and id.CAId = @CAId End else if @VN like 'SALE%' Begin select @Desc = id.[Desc] from SaleInvoiceMaster i  inner join SaleInvoiceDetail id on i.SaleInvoiceId = id.SaleInvoiceId where i.SaleInvoiceId = @VoucherId and id.CAId = @CAId End return @Desc  End